∀ {α : Type} (P : α → Prop) (Qs : List (α → Prop)),
  (∀ (Q : α → Prop), Q ∈ Qs → Foundations.Sets.Countable { x // Q x }) →
    (∀ (x : α), P x → ∃ Q, Q ∈ Qs ∧ Q x) → Foundations.Sets.Countable { x // P x }

∀ {C : Type u} [inst : Foundations.Categories.Category C] {T N : C} {z : Foundations.Categories.Category.Hom T N}
  {s : Foundations.Categories.Category.Hom N N} (hN : Foundations.Categories.IsNNO T N z s) {X : C}
  (f : Foundations.Categories.Category.Hom X X) {h k : Foundations.Categories.Category.Hom N X},
  Foundations.Categories.Category.comp z h = Foundations.Categories.Category.comp z k →
    Foundations.Categories.Category.comp s h = Foundations.Categories.Category.comp h f →
      Foundations.Categories.Category.comp s k = Foundations.Categories.Category.comp k f → h = k

{α : Type u} →
  {e : Nat → α} →
    (M : Foundations.Sets.SquareAbsorb.PSq e) → ({ x // M.dom x } → { x // ¬M.dom x }) → α → { x // M.dom x }

∀ (σ : Nat → Foundations.Logic.FO.Term Foundations.Logic.FO.Arith) (d n : Nat),
  Foundations.Logic.FO.liftN d σ n =
    if n < d then Foundations.Logic.FO.Term.var n else Foundations.Logic.FO.Term.rename (fun x => x + d) (σ (n - d))

∀ {Ω : Type u} [inst : Foundations.Algebra.CommRing Ω] (L : Foundations.Algebra.Subfield Ω) {ι : Type v}
  [inst_1 : Foundations.Algebra.FiniteType ι] (f : ι → { x // x ∈ L }),
  (Foundations.Algebra.isum f).val = Foundations.Algebra.isum fun i => (f i).val

∀ {α : Type} {P Q : α → Prop},
  Foundations.Sets.Countable { x // P x } →
    Foundations.Sets.Countable { x // Q x } → Foundations.Sets.Countable { x // P x ∨ Q x }

∀ (x : Foundations.Numbers.R),
  Foundations.Algebra.Polynomial.eval { re := x, im := 0 } (Foundations.Algebra.quinticPoly Foundations.Numbers.C) =
    { re := Foundations.Algebra.quinticR x, im := 0 }

∀ {L : Foundations.Logic.FO.Signature} {B : Type u} [inst : Foundations.Forcing.CompleteBooleanAlgebra B]
  {M : Foundations.Forcing.BStructure L B} {Γ : Foundations.Logic.FO.Theory L} {φ : Foundations.Logic.FO.Formula L}
  (e : Nat → M.Dom), Foundations.Forcing.CompleteBooleanAlgebra.inf (M.thVal Γ e) (M.val e φ) ≤ M.thVal (Γ.insert φ) e

∀ (θ : Foundations.Numbers.R) (n : Nat),
  { re := 0, im := θ } ^ n =
    { re := Foundations.Numbers.R.cosCoeff n * θ ^ n, im := Foundations.Numbers.R.sinCoeff n * θ ^ n }

∀ {Ω : Type u} [inst : Foundations.Algebra.CommRing Ω] {K : Foundations.Algebra.Subfield Ω} {α : Ω}
  (hΩ : Foundations.Algebra.IsField Ω) (C : Foundations.Algebra.CubicRoot K α),
  K.FiniteExt (Foundations.Algebra.CubicRoot.field hΩ C) ⋯ ∧ K.deg (Foundations.Algebra.CubicRoot.field hΩ C) ⋯ = 3

{G : Type u} →
  [inst : Foundations.Algebra.Group G] →
    (H : Foundations.Algebra.Subgroup G) → Foundations.Algebra.Subgroup { x // x ∈ Foundations.Algebra.normalizer H }

∀ {C : Type u} [inst : Foundations.Categories.Category C] {X Y P Q : C} {π₁ : Foundations.Categories.Category.Hom P X}
  {π₂ : Foundations.Categories.Category.Hom P Y} {ρ₁ : Foundations.Categories.Category.Hom Q X}
  {ρ₂ : Foundations.Categories.Category.Hom Q Y} (hP : Foundations.Categories.IsProduct X Y P π₁ π₂)
  (hQ : Foundations.Categories.IsProduct X Y Q ρ₁ ρ₂) (i : Foundations.Categories.Iso P Q),
  Foundations.Categories.Category.comp i.hom ρ₁ = π₁ →
    Foundations.Categories.Category.comp i.hom ρ₂ = π₂ → i = hP.uniqueIso hQ

(G : Type u) →
  [inst : Foundations.Algebra.Group G] →
    Foundations.Algebra.Iso G { x // x ∈ (Foundations.Algebra.leftRegular G).range }

∀ {C : Type u} [inst : Foundations.Categories.Category C] {X Y P : C} {π₁ : Foundations.Categories.Category.Hom P X}
  {π₂ : Foundations.Categories.Category.Hom P Y} (hP : Foundations.Categories.IsProduct X Y P π₁ π₂) {V W : C}
  (a : Foundations.Categories.Category.Hom V W) (f : Foundations.Categories.Category.Hom W X)
  (g : Foundations.Categories.Category.Hom W Y),
  Foundations.Categories.Category.comp a (hP.lift f g) =
    hP.lift (Foundations.Categories.Category.comp a f) (Foundations.Categories.Category.comp a g)

{α : Type u} →
  {e : Nat → α} →
    (M : Foundations.Sets.SquareAbsorb.PSq e) → ({ x // M.dom x } → { x // ¬M.dom x }) → α × α → { x // M.dom x }

∀ {X Y Z : Type} {τ : Foundations.Topology.Topology X} {σ : Foundations.Topology.Topology Y}
  {ρ : Foundations.Topology.Topology Z} {g : Y → Z} {f : X → Y},
  σ.Continuous ρ g → τ.Continuous σ f → τ.Continuous ρ fun x => g (f x)

∀ {C : Type u} [inst : Foundations.Categories.Category C] {T N N' : C} {z : Foundations.Categories.Category.Hom T N}
  {s : Foundations.Categories.Category.Hom N N} {z' : Foundations.Categories.Category.Hom T N'}
  {s' : Foundations.Categories.Category.Hom N' N'} (hN : Foundations.Categories.IsNNO T N z s)
  (hN' : Foundations.Categories.IsNNO T N' z' s') (h : Foundations.Categories.Category.Hom N N'),
  Foundations.Categories.Category.comp z h = z' →
    Foundations.Categories.Category.comp s h = Foundations.Categories.Category.comp h s' → h = (hN.uniqueIso hN').hom

∀ {X Y : Type} [inst : Foundations.Topology.MetricSpace X] [inst_1 : Foundations.Topology.MetricSpace Y] {A : X → Prop}
  {f : Y → X},
  Foundations.Topology.Continuous f → ∀ (h : ∀ (y : Y), A (f y)), Foundations.Topology.Continuous fun y => ⟨f y, ⋯⟩

∀ {Ω : Type u} [inst : Foundations.Algebra.CommRing Ω] {F M : Foundations.Algebra.Subfield Ω}
  (a b : Foundations.Algebra.FieldAut F M) (x : { x // x ∈ M }),
  a⁻¹.toFun (b⁻¹.toFun x) = b⁻¹.toFun (a⁻¹.toFun x) → (Foundations.Algebra.commutator a b).toFun x = x

{S : Type v} →
  [inst : Foundations.Algebra.CommRing S] →
    (A : Foundations.Algebra.Subring S) → Foundations.Algebra.CommRing { x // x ∈ A }

{C : Type u} →
  [inst : Foundations.Categories.Category C] →
    {X Y : C} → Foundations.Categories.Iso X Y → Foundations.Categories.Iso { unop := X } { unop := Y }

∀ {C : Type u} [inst : Foundations.Categories.Category C] {X Y E E' : C} {f g : Foundations.Categories.Category.Hom X Y}
  {e : Foundations.Categories.Category.Hom E X} {e' : Foundations.Categories.Category.Hom E' X}
  (hE : Foundations.Categories.IsEqualizer f g E e) (hE' : Foundations.Categories.IsEqualizer f g E' e')
  (i : Foundations.Categories.Iso E E'), Foundations.Categories.Category.comp i.hom e' = e → i = hE.uniqueIso hE'

∀ {Ω : Type u} [inst : Foundations.Algebra.CommRing Ω] {K : Foundations.Algebra.Subfield Ω} {α : Ω}
  (hΩ : Foundations.Algebra.IsField Ω) (C : Foundations.Algebra.CubicRoot K α),
  α ∈ Foundations.Algebra.CubicRoot.field hΩ C

∀ {Ω : Type u} [inst : Foundations.Algebra.CommRing Ω] {K L : Foundations.Algebra.Subfield Ω}
  (σ : Foundations.Algebra.FieldAut K L) (x : { x // x ∈ L }) (n : Nat),
  σ.toFun (Foundations.Algebra.rpow x n) = Foundations.Algebra.rpow (σ.toFun x) n

∀ {K : Foundations.Algebra.Subfield Foundations.Numbers.C} {x : Foundations.Numbers.C}
  (h : Foundations.Algebra.IsAlgebraic K x),
  Foundations.Algebra.adj K x = Foundations.Algebra.adjoin Foundations.Algebra.C.isField K x h

∀ {C : Type u} [inst : Foundations.Categories.Category C] {X Y P : C} {π₁ : Foundations.Categories.Category.Hom P X}
  {π₂ : Foundations.Categories.Category.Hom P Y} (hP : Foundations.Categories.IsProduct X Y P π₁ π₂) {W : C}
  {h k : Foundations.Categories.Category.Hom W P},
  Foundations.Categories.Category.comp h π₁ = Foundations.Categories.Category.comp k π₁ →
    Foundations.Categories.Category.comp h π₂ = Foundations.Categories.Category.comp k π₂ → h = k

∀ {X Y Z : Type} {ρ : Foundations.Topology.Topology Z} {τ : Foundations.Topology.Topology X}
  {σ : Foundations.Topology.Topology Y} {f : Z → X} {g : Z → Y},
  ρ.Continuous τ f → ρ.Continuous σ g → ρ.Continuous (τ.prod σ) fun z => (f z, g z)

∀ {G : Type u} [inst : Foundations.Algebra.Group G] [inst_1 : Foundations.Algebra.FiniteType G]
  (H : Foundations.Algebra.Subgroup G),
  Foundations.Algebra.FiniteType.card { x // x ∈ H.inNormalizer } = Foundations.Algebra.FiniteType.card { x // x ∈ H }

∀ {Ω : Type u} [inst : Foundations.Algebra.CommRing Ω] {K L : Foundations.Algebra.Subfield Ω}
  (σ : Foundations.Algebra.FieldAut K L) {ι : Type v} [inst_1 : Foundations.Algebra.FiniteType ι]
  (f : ι → { x // x ∈ L }), σ.toFun (Foundations.Algebra.isum f) = Foundations.Algebra.isum fun i => σ.toFun (f i)

∀ {F : Foundations.Algebra.Subfield Foundations.Numbers.C}
  (τ : Foundations.Algebra.RingHom { x // x ∈ F } Foundations.Numbers.C) (x : { x // x ∈ F }),
  x.val ∈ Foundations.Algebra.Qc → τ.toFun x = x.val

∀ {Ω : Type u} [inst : Foundations.Algebra.CommRing Ω] {K : Foundations.Algebra.Subfield Ω} {α : Ω}
  (hΩ : Foundations.Algebra.IsField Ω) (C : Foundations.Algebra.CubicRoot K α),
  K.le (Foundations.Algebra.CubicRoot.field hΩ C)

∀ {Ω : Type u} [inst : Foundations.Algebra.CommRing Ω] {K : Foundations.Algebra.Subfield Ω}
  (S : Foundations.Algebra.KSubspace K) {ι : Type v} [inst_1 : Foundations.Algebra.FiniteType ι]
  (f : ι → { x // S.carrier x }), (Foundations.Algebra.isum f).val = Foundations.Algebra.isum fun i => (f i).val

∀ {Ω : Type u} [inst : Foundations.Algebra.CommRing Ω] {K : Foundations.Algebra.Subfield Ω} {α : Ω}
  (hΩ : Foundations.Algebra.IsField Ω) (C : Foundations.Algebra.CubicRoot K α) {F : Foundations.Algebra.Subfield Ω},
  K.le F → α ∈ F → (Foundations.Algebra.CubicRoot.field hΩ C).le F

∀ {Ω : Type u} [inst : Foundations.Algebra.CommRing Ω] (hΩ : Foundations.Algebra.IsField Ω)
  (hc : Foundations.Algebra.CharZero Ω) {α : Ω}
  (C : Foundations.Algebra.CubicRoot (Foundations.Algebra.ratField hΩ hc) α), ¬Foundations.Algebra.Constructible hΩ hc α

∀ {C : Type u} [inst : Foundations.Categories.Category C] {X Y E : C} {f g : Foundations.Categories.Category.Hom X Y}
  {e : Foundations.Categories.Category.Hom E X} (hE : Foundations.Categories.IsEqualizer f g E e) {W : C}
  {h k : Foundations.Categories.Category.Hom W E},
  Foundations.Categories.Category.comp h e = Foundations.Categories.Category.comp k e → h = k

∀ {G : Type u} [inst : Foundations.Algebra.Group G] {N : Foundations.Algebra.Subgroup G}
  {P : Foundations.Algebra.QuotientGroup N → Prop},
  (∀ (a : G), P (Foundations.Algebra.QuotientGroup.mk N a)) → ∀ (q : Foundations.Algebra.QuotientGroup N), P q

∀ {X Y : Foundations.Bridges.ZFCat}
  (f : Foundations.Categories.Category.Hom (Foundations.Bridges.El.obj X) (Foundations.Bridges.El.obj Y)),
  ∃ F, Foundations.Bridges.El.map F = f
